/**
 * Ein Graph, gespeichert als Adjazenzmatrix (wie in Station 3.2).
 * Suche (Strg + F) nach "TODO" und ergänze den Code.
 */
public class Graph {
   Knoten[] knoten;     // knoten[i] ist der Knoten mit der Nummer i
   boolean[][] adja;    // adja[start][ende] ist true, wenn es eine Kante gibt
   int maxAnzahl = 20;  // so viele Plätze haben die Felder
   int anzKnoten = 5;   // so viele Plätze sind belegt

   Graph() {
      knoten = new Knoten[maxAnzahl];
      adja = new boolean[maxAnzahl][maxAnzahl];
      for (int i = 0; i < anzKnoten; i++) {
         erzeugeKnoten(i);
      }
   }

   /**
    * Breitensuche von startKnoten aus, bis zielKnoten gefunden ist.
    * Pseudocode und Codefragmente: Blatt 3.3, Aufgabe 3.
    */
   void breitensuche(int startKnoten, int zielKnoten) {
      LinkedList<Integer> besuchteKnoten = new LinkedList<Integer>();
      LinkedList<Integer> warteschlange = new LinkedList<Integer>();

      // TODO 1: Fragmente für die ersten drei Zeilen des Pseudocodes
      int aktuellerKnoten = startKnoten;              // 2
      warteschlange.add(aktuellerKnoten);             // 1
      print("Reihenfolge: ");                         // 7

      // zur Visualisierung: alle Knoten grau
      for (int i = 0; i < anzKnoten; i++) {
         knoten[i].setFillColor(Color.gray);
      }

      // TODO 2: die Wiederholung "solange ..." mit ihrem Inhalt.
      while (aktuellerKnoten != zielKnoten && !warteschlange.isEmpty()) {   // 6
         aktuellerKnoten = warteschlange.poll();      // 4
         besuchteKnoten.add(aktuellerKnoten);         // 8
         print(aktuellerKnoten + " ");                // 3
         knoten[aktuellerKnoten].setFillColor(Color.green);
         for (int i = 0; i < anzKnoten; i++) {        // 5
            if (adja[aktuellerKnoten][i] && !besuchteKnoten.contains(i) && !warteschlange.contains(i)) {   // 9
               warteschlange.addLast(i);
            }
         }
      }

      // TODO 3: Endüberprüfung und Ausgabe (Fragment 10)
      println();
      if (aktuellerKnoten == zielKnoten) {
         println("Es gibt einen Pfad von Knoten " + startKnoten + " zu Knoten " + zielKnoten);
         new Text(125, 700, 64, "GEFUNDEN!");
      } else {
         println("Knoten konnte nicht gefunden werden");
         new Text(50, 700, 64, "NICHT gefunden!");
      }

   }

   // ----- fertige Methoden aus Station 3.2, müssen nicht verändert werden -----

   // Fügt eine ungerichtete Kante zwischen start und ende hinzu.
   void kanteHinzufuegen(int start, int ende) {
      if (start < 0 || start >= anzKnoten || ende < 0 || ende >= anzKnoten) {
         println("Einfügen nicht möglich.");
      } else {
         adja[start][ende] = true;
         adja[ende][start] = true;
         zeichneKante(start, ende);
      }
   }

   // Fügt einen neuen Knoten ohne Kanten hinzu, solange Platz ist.
   void knotenHinzufuegen() {
      if (anzKnoten < maxAnzahl) {
         erzeugeKnoten(anzKnoten);
         anzKnoten++;
      } else {
         println("Einfügen nicht möglich.");
      }
   }

   // Gibt die Adjazenzmatrix mit X (Kante) und O (keine Kante) aus.
   void printAdja() {
      for (int zeile = 0; zeile < anzKnoten; zeile++) {
         for (int spalte = 0; spalte < anzKnoten; spalte++) {
            if (adja[zeile][spalte]) {
               print("X ");
            } else {
               print("O ");
            }
         }
         println();
      }
      println();
   }

   // Gibt alle Nachbarn von Knoten k aus.
   void nachbarnAusgeben(int k) {
      print("Nachbarn von " + k + ": ");
      for (int i = 0; i < anzKnoten; i++) {
         if (adja[k][i]) {
            print(i + " ");
         }
      }
      println();
   }

   // Erzeugt Knoten Nummer i und ordnet ihn an (nur für die Darstellung).
   void erzeugeKnoten(int i) {
      knoten[i] = new Knoten();
      knoten[i].setKnotenname("" + i);
      knoten[i].moveTo(100 + (i % 3) * 200, 100 + i * 100);
      new Text(knoten[i].getCenterX() - 8, knoten[i].getCenterY() - 16, 32, "" + i);
   }

   // Zeichnet eine Kante als halbtransparenten Balken.
   void zeichneKante(int start, int ende) {
      double startX = knoten[start].getCenterX();
      double startY = knoten[start].getCenterY();
      double endeX = knoten[ende].getCenterX();
      double endeY = knoten[ende].getCenterY();

      double abstand = Vector2.distance(startX, startY, endeX, endeY);
      double winkel = new Vector2(endeX - startX, endeY - startY).getAngleDeg();

      Rectangle balken = new Rectangle(startX, startY, 10, abstand);
      balken.setFillColor(Color.white);
      balken.setAlpha(0.6);
      balken.rotate(90 - winkel, startX, startY);
   }
}

class Knoten extends Circle {
   private String knotenname = "Knoten X";

   Knoten() {
      setFillColor(Color.orange);
   }

   String getKnotenname() {
      return knotenname;
   }

   void setKnotenname(String knotenname) {
      this.knotenname = knotenname;
   }
}
